               que difere do ultimo valor marcado (sempre otimo,
               pois antecipar uma ocorrencia nunca piora o futuro) */
            for (int i = 0; i < n; i++) {
                int x = v[i];
                if ((x == a || x == b) && x != last) {
                    len++;
                    last = x;
                }
            }
            if (len > best) best = len;
        }
    }

    printf("%d\n", best);
